# R golden fixtures for gaply_core's descriptive summary (Research OS, Phase 2A).
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_desc_fixtures.R
#
# Writes, next to this script: one synthetic data CSV per dataset
# (data_*.csv, a two-line '#' header then the CSV), then golden.csv with R's
# answer for every case. Every data file is written, READ BACK with
# read.csv(na.strings = ""), and the summary is computed on what was read, so
# R computed on exactly the text gaply_core parses. A missing cell is an empty
# field. Every file has an `id` column, so no data line is ever blank
# (read.csv skips blank lines, and Gaply does not).
#
# Columns of golden.csv:
#   case           a unique name
#   data           the data file
#   column         the column's header
#   treat_as       numeric or categorical
#   missing_codes  the codes the case treats as missing, ';'-separated, or empty
#   statistic      n, missing, mean, sd, min, q1, median, q3, max (numeric);
#                  n, missing, count (categorical, one count row per level)
#   level          the level's label on a count row, else empty
#   value          %.17g, or NA where R gives no number (n = 0; sd with n < 2)
#
# Also writes cells_bits.csv: the IEEE 754 bit pattern of every number R
# read from every data file (data, column, row, bits), so the Rust test can
# check that both sides parsed every cell to the same double. R's own parser
# is not correctly rounded for every spelling (it misreads some e-notation by
# one unit in the last place), so this is measured, not assumed.
#
# Definitions: sd with the n - 1 denominator (sd); quartiles by R's default,
# quantile(type = 7); levels sorted with sort(method = "radix"), which orders
# character strings by code point whatever the locale.
#
# Synthetic data only. No manuscript or data of anyone's is read.

args <- commandArgs(trailingOnly = FALSE)
script <- sub("^--file=", "", args[grep("^--file=", args)])
here <- dirname(normalizePath(script))

f17 <- function(x) ifelse(is.na(x), "NA", sprintf("%.17g", as.numeric(x)))

rows <- list()
cell_bits <- list()
add <- function(case, data, column, treat_as, codes, statistic, level, value) {
  rows[[length(rows) + 1]] <<- data.frame(
    case = case, data = data, column = column, treat_as = treat_as,
    missing_codes = paste(codes, collapse = ";"), statistic = statistic,
    level = level, value = value, stringsAsFactors = FALSE)
}

# Write `df`, read it back, return what was read. The provenance header is
# prepended AFTER the read, so the lines R analysed are exactly the lines
# below the '#' header that the Rust test parses.
roundtrip <- function(df, name) {
  path <- file.path(here, name)
  write.csv(df, path, row.names = FALSE, quote = FALSE, na = "", fileEncoding = "UTF-8")
  back <- read.csv(path, na.strings = "", stringsAsFactors = FALSE, encoding = "UTF-8")
  for (column in names(back)) {
    v <- back[[column]]
    if (is.numeric(v)) {
      for (i in which(!is.na(v))) {
        b <- paste(as.character(writeBin(as.numeric(v[i]), raw(), size = 8, endian = "big")), collapse = "")
        cell_bits[[length(cell_bits) + 1]] <<- data.frame(data = name, column = column, row = i, bits = b, stringsAsFactors = FALSE)
      }
    }
  }
  body <- readLines(path, encoding = "UTF-8")
  writeLines(c(
    "# Synthetic data for gaply_core's descriptive-summary R golden fixtures (Research OS, Phase 2A).",
    "# Generated by /usr/local/bin/Rscript make_desc_fixtures.R (do not edit by hand).",
    body), path, useBytes = TRUE)
  back
}

numeric_case <- function(case, name, d, column, codes = numeric(0)) {
  x <- d[[column]]
  if (length(codes)) x[x %in% codes] <- NA
  v <- x[!is.na(x)]
  n <- length(v)
  add(case, name, column, "numeric", codes, "n", "", as.character(n))
  add(case, name, column, "numeric", codes, "missing", "", as.character(sum(is.na(x))))
  q <- if (n == 0) c(NA, NA, NA) else quantile(v, c(0.25, 0.5, 0.75), type = 7, names = FALSE)
  stats <- list(
    mean = if (n == 0) NA else mean(v),
    sd = if (n < 2) NA else sd(v),
    min = if (n == 0) NA else min(v),
    q1 = q[1], median = q[2], q3 = q[3],
    max = if (n == 0) NA else max(v))
  for (s in names(stats)) add(case, name, column, "numeric", codes, s, "", f17(stats[[s]]))
}

# `codes` is recorded on every row and NOT applied: a missing code applies to
# Numeric requests only, and a categorical column keeps it as a level
# (decision 38, evaluation of Research OS Phases 2 and 3, F5).
categorical_case <- function(case, name, d, column, codes = numeric(0)) {
  x <- d[[column]]
  x <- as.character(x)
  v <- x[!is.na(x)]
  add(case, name, column, "categorical", codes, "n", "", as.character(length(v)))
  add(case, name, column, "categorical", codes, "missing", "", as.character(sum(is.na(x))))
  levels <- sort(unique(v), method = "radix")
  counts <- table(factor(v, levels = levels))
  for (l in levels) add(case, name, column, "categorical", codes, "count", l, as.character(counts[[l]]))
}

with_id <- function(...) {
  d <- data.frame(..., stringsAsFactors = FALSE)
  cbind(id = seq_len(nrow(d)), d)
}

set.seed(20261017)

# 1. Integers, also read as categorical (levels "1", "10", "100", "11", ...).
d <- roundtrip(with_id(x = sample(1:100, 30, replace = TRUE)), "data_integers.csv")
numeric_case("integers", "data_integers.csv", d, "x")
categorical_case("integers_as_categorical", "data_integers.csv", d, "x")

# 2. Values with two decimals.
d <- roundtrip(with_id(x = round(rnorm(40, 50, 12), 2)), "data_two_decimals.csv")
numeric_case("two_decimals", "data_two_decimals.csv", d, "x")

# 3. Constant columns: 7.25 (exact in binary) and 0.1 (not), so the floating
#    mean is not the value; sd must be exactly 0 for both.
d <- roundtrip(with_id(x = rep(7.25, 15), y = rep(0.1, 15)), "data_constant.csv")
numeric_case("constant", "data_constant.csv", d, "x")
numeric_case("constant_tenth", "data_constant.csv", d, "y")

# 4. 40% missing: 20 of 50 cells empty.
x <- round(rnorm(50, 20, 4), 1)
x[sample(50, 20)] <- NA
d <- roundtrip(with_id(x = x), "data_missing40.csv")
numeric_case("missing40", "data_missing40.csv", d, "x")

# 5. Every cell missing, as numeric and as categorical.
d <- roundtrip(with_id(x = rep(NA_real_, 10)), "data_all_missing.csv")
numeric_case("all_missing", "data_all_missing.csv", d, "x")
categorical_case("all_missing_as_categorical", "data_all_missing.csv", d, "x")

# 6. A single row: sd is not computable.
d <- roundtrip(with_id(x = 3.14159), "data_single_row.csv")
numeric_case("single_row", "data_single_row.csv", d, "x")

# 7. Offset 1e9 with SD 10 (the m-10 class).
d <- roundtrip(with_id(x = round(1e9 + rnorm(60, 0, 10), 4)), "data_offset.csv")
numeric_case("offset_1e9", "data_offset.csv", d, "x")

# 8. 5,000 rows.
d <- roundtrip(with_id(x = round(rnorm(5000, 100, 15), 3)), "data_large.csv")
numeric_case("large_5000", "data_large.csv", d, "x")

# 9. A categorical column: mixed case, a leading underscore, digit strings
#    that sort as text ("10" before "9"), and a non-ASCII label; 8 missing.
labels <- c("alpha", "beta", "Gamma", "delta", "zeta", "Éclair", "_under", "10", "9")
g <- sample(labels, 80, replace = TRUE)
g[sample(80, 8)] <- NA
d <- roundtrip(with_id(g = g), "data_categorical.csv")
categorical_case("categorical", "data_categorical.csv", d, "g")

# 10. A rating scale 1..7 holding -99 as a code: without and with
#     missing_codes = [-99]; also as categorical with the code listed, which
#     keeps -99 as a level (decision 38).
x <- sample(1:7, 60, replace = TRUE)
x[sample(60, 6)] <- -99
x[sample(which(x != -99), 4)] <- NA
d <- roundtrip(with_id(x = x), "data_coded.csv")
numeric_case("coded_raw", "data_coded.csv", d, "x")
numeric_case("coded_missing_99", "data_coded.csv", d, "x", codes = -99)
categorical_case("coded_missing_99_as_categorical", "data_coded.csv", d, "x", codes = -99)

# 11. Negative values.
d <- roundtrip(with_id(x = round(rnorm(25, -40, 8), 2)), "data_negative.csv")
numeric_case("negative", "data_negative.csv", d, "x")

# 12. Heavy tails: Student t with 1.5 df, scaled.
d <- roundtrip(with_id(x = round(rt(200, df = 1.5) * 5, 3)), "data_heavy_tail.csv")
numeric_case("heavy_tail", "data_heavy_tail.csv", d, "x")

# 13. Four values, so every quartile interpolates; and a column whose
#     interpolation partners are tied.
d <- roundtrip(with_id(x = c(1, 2, 4, 8), y = c(5, 5, 5, 6)), "data_small_even.csv")
numeric_case("small_even", "data_small_even.csv", d, "x")
numeric_case("small_even_ties", "data_small_even.csv", d, "y")

out <- do.call(rbind, rows)
path <- file.path(here, "golden.csv")
con <- file(path, open = "w", encoding = "UTF-8")
writeLines(c(
  "# R golden values for gaply_core's descriptive summary (Research OS, Phase 2A).",
  "# Generated by /usr/local/bin/Rscript make_desc_fixtures.R (do not edit by hand).",
  paste0("# ", R.version.string, ", ", R.version$arch, "; set.seed(20261017)."),
  "# sd n-1; quartiles quantile(type = 7); levels sort(method = \"radix\"); numbers %.17g; NA where R gives none."),
  con)
write.table(out, con, sep = ",", quote = FALSE, row.names = FALSE, col.names = TRUE)
close(con)
bits <- do.call(rbind, cell_bits)
con <- file(file.path(here, "cells_bits.csv"), open = "w", encoding = "UTF-8")
writeLines(c(
  "# The IEEE 754 bits (big-endian hex) of every number R read from each data file (Research OS, Phase 2A).",
  "# Generated by /usr/local/bin/Rscript make_desc_fixtures.R (do not edit by hand)."),
  con)
write.table(bits, con, sep = ",", quote = FALSE, row.names = FALSE, col.names = TRUE)
close(con)
cat("wrote", nrow(out), "golden rows for", length(unique(out$case)), "cases and the bits of", nrow(bits), "cells\n")
